import AppKit

/// Source asset: assets/cursor.png (whole image, 64x64, hotspot at top-left).
/// The overlay draws it at 28x28 points with the top-left corner at the target.
/// Embedded transparent cursor image for the Agent cursor overlay.
enum EmbeddedCursorImage {
    static let image: NSImage? = {
        guard let data = Data(base64Encoded: "") else { return nil }
        return NSImage(data: data)
    }()
}
